// Racines de scan (README§Scan Sources)
const SCAN_ROOTS = [
  'AI', 'agent', 'agentic', 'GenAI', 'automation',
  'LLM', 'RAG', 'ML', 'full stack', 'n8n', 'Python', 'developer'
];

const HYBRID_THRESHOLD = 10;  // Déclencher passe hybrid si remote < seuil
const GLOBAL_CAP = 60;         // Cap global toutes passes confondues

// Construire la liste des requêtes passe 1 (remote)
return SCAN_ROOTS.map(root => ({
  json: { root, pass: 'remote', hybridThreshold: HYBRID_THRESHOLD, globalCap: GLOBAL_CAP }
}));

// Agréger les résultats remote de tous les roots
// Dédupliquer par URL

const seenUrls = new Set();
const remoteOffers = [];

for (const item of $input.all()) {
  const body = item.json;
  // Extraire les offres depuis la réponse MCP
  const content = body?.result?.content ?? [];
  let offers = [];
  if (content.length > 0) {
    try {
      offers = JSON.parse(content[0].text ?? '[]');
    } catch (_) {
      // Certains serveurs retournent directement dans result
      offers = body?.result?.jobs ?? body?.result?.results ?? body?.result?.items ?? [];
    }
  } else {
    // Fallback : chercher dans plusieurs clés
    const raw = body?.result ?? body;
    offers = raw?.jobs ?? raw?.results ?? raw?.items ?? raw?.offers ?? raw?.data ?? [];
  }
  if (!Array.isArray(offers)) offers = [];

  for (const offer of offers) {
    const url = offer.url ?? offer.link ?? offer.jobUrl ?? offer.applyUrl ?? offer.detailsPageUrl ?? '';
    if (url && !seenUrls.has(url)) {
      seenUrls.add(url);
      remoteOffers.push({
        url,
        title:       offer.title ?? offer.jobTitle ?? offer.name ?? '',
        company:     offer.company ?? offer.companyName ?? offer.employer ?? '',
        location:    offer.location ?? offer.formattedLocation ?? offer.city ?? '',
        description: (offer.description ?? offer.snippet ?? offer.summary ?? '').substring(0, 500),
        job_type:    offer.jobType ?? offer.job_type ?? offer.employmentType ?? '',
        date_posted: offer.datePosted ?? offer.date_posted ?? offer.postedAt ?? offer.formattedRelativeTime ?? '',
        source:      'indeed',
        _pass:       1
      });
    }
  }
}

const hybridThreshold = $input.first()?.json?.hybridThreshold ?? 10;
const globalCap       = $input.first()?.json?.globalCap ?? 60;

return [{
  json: {
    remoteOffers: remoteOffers.slice(0, globalCap),
    remoteCount:  remoteOffers.length,
    needHybrid:   remoteOffers.length < hybridThreshold,
    hybridThreshold,
    globalCap
  }
}];

// Passe 2 : Hybrid — construire les requêtes pour les 12 racines
const SCAN_ROOTS = [
  'AI', 'agent', 'agentic', 'GenAI', 'automation',
  'LLM', 'RAG', 'ML', 'full stack', 'n8n', 'Python', 'developer'
];

const state = $input.first().json;

return SCAN_ROOTS.map(root => ({
  json: {
    root,
    pass:         'hybrid',
    remoteOffers: state.remoteOffers,
    remoteCount:  state.remoteCount,
    globalCap:    state.globalCap
  }
}));

// Fusionner les résultats hybrid avec les résultats remote
// Dédupliquer par URL, appliquer cap global

const first = $input.first().json;
const remoteOffers = first.remoteOffers ?? [];
const globalCap    = first.globalCap ?? 60;

// Reconstruire le set des URLs déjà vues (remote)
const seenUrls = new Set(remoteOffers.map(o => o.url).filter(Boolean));
const hybridOffers = [];

for (const item of $input.all()) {
  const body = item.json;
  const content = body?.result?.content ?? [];
  let offers = [];
  if (content.length > 0) {
    try {
      offers = JSON.parse(content[0].text ?? '[]');
    } catch (_) {
      offers = body?.result?.jobs ?? body?.result?.results ?? body?.result?.items ?? [];
    }
  } else {
    const raw = body?.result ?? body;
    offers = raw?.jobs ?? raw?.results ?? raw?.items ?? raw?.offers ?? raw?.data ?? [];
  }
  if (!Array.isArray(offers)) offers = [];

  for (const offer of offers) {
    if (seenUrls.size >= globalCap) break;
    const url = offer.url ?? offer.link ?? offer.jobUrl ?? offer.applyUrl ?? '';
    if (url && !seenUrls.has(url)) {
      seenUrls.add(url);
      hybridOffers.push({
        url,
        title:       offer.title ?? offer.jobTitle ?? offer.name ?? '',
        company:     offer.company ?? offer.companyName ?? offer.employer ?? '',
        location:    offer.location ?? offer.formattedLocation ?? offer.city ?? '',
        description: (offer.description ?? offer.snippet ?? offer.summary ?? '').substring(0, 500),
        job_type:    offer.jobType ?? offer.job_type ?? offer.employmentType ?? '',
        date_posted: offer.datePosted ?? offer.date_posted ?? offer.postedAt ?? offer.formattedRelativeTime ?? '',
        source:      'indeed',
        _pass:       2
      });
    }
  }
}

const allOffers = [...remoteOffers, ...hybridOffers].slice(0, globalCap);

return [{
  json: {
    offers:      allOffers,
    totalCount:  allOffers.length,
    remoteCount: remoteOffers.length,
    hybridCount: hybridOffers.length,
    scanDate:    new Date().toISOString()
  }
}];
